{
  "name": "opencode-session-reflection",
  "version": "0.4.0",
  "description": "Turn OpenCode session failures into reusable reliability improvements.",
  "type": "module",
  "main": "./src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "src",
    "commands",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test \"test/*.test.mjs\"",
    "check:import": "node -e \"import('./src/index.js').then((m) => { const d = m.default; if (typeof d?.server !== 'function' || typeof d.id !== 'string') throw new Error('default export is not a V1 plugin module with id and server()'); console.log('plugin import ok') })\"",
    "prepublishOnly": "npm test && npm run check:import",
    "deploy": "node scripts/deploy.js",
    "undeploy": "node scripts/undeploy.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "session-review",
    "reflection",
    "ai-agents",
    "developer-productivity"
  ],
  "repository": {
    "type": "git",
    "url": "git+ssh://git@github.com/chncaesar/opencode-session-reflection.git"
  },
  "bugs": {
    "url": "https://github.com/chncaesar/opencode-session-reflection/issues"
  },
  "homepage": "https://github.com/chncaesar/opencode-session-reflection#readme",
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.11"
  },
  "engines": {
    "node": ">=22.5.0"
  }
}
